select a.*
from (select b.*,
             CASE WHEN b.INVALID_DATE IS NOT NULL AND  b.INVALID_DATE < DATE(NOW()) then '失效'
              ELSE '正常'  END AS copyrightStatus
      from SOFTWARE_COPYRIGHT b where b.DELETE_FLAG='NOT_DELETE') a
